import IdentityVerifyPanel from './IdentityVerifyPanel'
import KlmPrefixInput from './KlmPrefixInput'

export function CheckStatusPanel({ flow }) {
  if (flow.statusPath === 'identity') {
    return (
      <IdentityVerifyPanel
        identityOptions={flow.identityOptions}
        formLabelConfigs={flow.formLabelConfigs}
        contextNumber={flow.claimNumber}
        loading={flow.loading}
        serverError={flow.identityError}
        onClearServerError={flow.clearIdentityError}
        backLabelId="Ubah Nomor Klaim"
        onBack={flow.backFromIdentity}
        onVerify={flow.verifyStatusIdentity}
      />
    )
  }

  return (
    <div data-testid="login-check-status">
      <KlmPrefixInput onComplete={flow.advanceStatusClaimNumber} />
    </div>
  )
}
