import { useCallback, useEffect, useRef, useState } from 'react'
import ReactCountryFlag from 'react-country-flag'
import { connect } from 'react-redux'
import { FormattedMessage, injectIntl } from 'react-intl'
import TextInput from '../../../../../../components/v2/TextInput'
import CaptchaField from '../../../../../../components/v2/CaptchaField'
import { ArrowDown } from '../../../../../../components/v2/icons'
import {
  PrimaryBtn,
  PrimaryBtnText,
  Spinner,
} from '../../../../../../components/v2/Button'
import { COUNTRY_CODES, getDefaultCountry } from '../countryCodes'
import { InlineFieldGrow, InlineFieldRow } from './InlineFieldRow'
import { LoginV3SecondaryButton } from './LoginV3SecondaryButton'
import { ModeDivider } from './ModeDivider'
import { TermsCheckbox } from './TermsCheckbox'
import {
  CaptchaSection,
  CountryBtn,
  DropdownItem,
  DropdownList,
  ErrorText,
  OutlineBackBtn,
  PhoneSubmitRow,
  PolicyStepHeader,
  SectionSubtitle,
  SectionTitle,
  Space16,
  StepFormColumn,
  TermsSection,
} from '../styles'

function PhoneModeV3({
  onSendOtp,
  onSwitchToPolicy,
  onBack,
  language,
  showPolicyToggle,
  requireCaptcha = true,
  intl,
}) {
  const locale = (language && language.locale) || 'id'
  const [phone, setPhone] = useState('')
  const [checked, setChecked] = useState(false)
  const [captchaToken, setCaptchaToken] = useState('')
  const [errors, setErrors] = useState({})
  const [loading, setLoading] = useState(false)
  const [country, setCountry] = useState(() => getDefaultCountry(locale))
  const [dropdownOpen, setDropdownOpen] = useState(false)
  const dropdownRef = useRef(null)

  useEffect(() => {
    setCountry(getDefaultCountry(locale))
  }, [locale])

  useEffect(() => {
    const onClick = (e) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
        setDropdownOpen(false)
      }
    }
    if (dropdownOpen) document.addEventListener('mousedown', onClick)
    return () => document.removeEventListener('mousedown', onClick)
  }, [dropdownOpen])

  const handleToggleChecked = useCallback(() => {
    if (!loading) setChecked((v) => !v)
  }, [loading])

  const captchaReady = !requireCaptcha || captchaToken.length > 0
  const canSubmit = phone.trim().length > 0 && checked && captchaReady

  const handleSubmit = useCallback(() => {
    if (!canSubmit) return
    setErrors({})
    setLoading(true)
    onSendOtp(country, phone, captchaToken, (error) => {
      setLoading(false)
      if (error) setErrors((e) => ({ ...e, general: error }))
    })
  }, [canSubmit, country, phone, captchaToken, onSendOtp])

  return (
    <div data-testid="login-phone-mode">
      <PolicyStepHeader>
        <SectionTitle>
          <FormattedMessage id="Masukkan" />
          <span className="accent">
            {' '}
            <FormattedMessage id="Nomor Ponsel" />{' '}
          </span>
          <FormattedMessage id="pemegang polis untuk verifikasi data" />
        </SectionTitle>
        <SectionSubtitle>
          (
          <FormattedMessage id="Hanya nomor ponsel pemegang polis yang berlaku" />
          )
        </SectionSubtitle>
      </PolicyStepHeader>

      <StepFormColumn>
      <InlineFieldRow stacked>
        <InlineFieldGrow>
          <div style={{ display: 'flex', gap: 8, minWidth: 0 }}>
            <div
              ref={dropdownRef}
              style={{ position: 'relative', flexShrink: 0 }}
            >
              <CountryBtn
                type="button"
                error={!!errors.phone}
                onClick={() => setDropdownOpen((v) => !v)}
                disabled={loading}
              >
                <ReactCountryFlag
                  countryCode={country.countryCode}
                  svg
                  style={{ width: 20, height: 20, borderRadius: 8 }}
                />
                <span style={{ fontSize: 14, fontWeight: 800 }}>
                  +{country.value}
                </span>
                <ArrowDown isOpen={dropdownOpen} />
              </CountryBtn>
              {dropdownOpen ? (
                <DropdownList>
                  {COUNTRY_CODES.map((c) => (
                    <li key={`${c.countryCode}-${c.value}`}>
                      <DropdownItem
                        type="button"
                        selected={
                          c.countryCode === country.countryCode &&
                          c.value === country.value
                        }
                        onClick={() => {
                          setCountry(c)
                          setDropdownOpen(false)
                        }}
                      >
                        <ReactCountryFlag
                          countryCode={c.countryCode}
                          svg
                          style={{ width: 20, height: 15 }}
                        />
                        {c.displayName}
                      </DropdownItem>
                    </li>
                  ))}
                </DropdownList>
              ) : null}
            </div>
            <div style={{ flex: 1, minWidth: 0 }}>
              <TextInput
                label={intl.formatMessage({ id: 'Nomor Ponsel' })}
                value={phone}
                onChange={setPhone}
                error={!!errors.phone}
                helperText={errors.phone || ''}
                disabled={loading}
              />
            </div>
          </div>
        </InlineFieldGrow>
      </InlineFieldRow>

      {requireCaptcha ? (
        <CaptchaSection data-testid="login-phone-captcha">
          <CaptchaField onVerify={setCaptchaToken} />
        </CaptchaSection>
      ) : null}

      <TermsSection>
        <TermsCheckbox
          checked={checked}
          onToggle={handleToggleChecked}
          disabled={loading}
        />
        {errors.general ? <ErrorText>{errors.general}</ErrorText> : null}
      </TermsSection>

      <PhoneSubmitRow>
        <PrimaryBtn
          onClick={handleSubmit}
          disabled={loading || !canSubmit}
          className={!canSubmit ? 'login-v3-btn-disabled' : ''}
        >
          {loading && <Spinner />}
          <PrimaryBtnText>
            <FormattedMessage id="Kirim OTP" />
          </PrimaryBtnText>
        </PrimaryBtn>
      </PhoneSubmitRow>

      {onBack ? (
        <Space16>
          <OutlineBackBtn type="button" onClick={onBack} disabled={loading}>
            ← <FormattedMessage id="Kembali" />
          </OutlineBackBtn>
        </Space16>
      ) : null}

      {showPolicyToggle && onSwitchToPolicy ? (
        <>
          <ModeDivider />
          <LoginV3SecondaryButton
            onClick={onSwitchToPolicy}
            testId="login-switch-policy"
          >
            <FormattedMessage id="Masuk Menggunakan Nomor Polis" />
          </LoginV3SecondaryButton>
        </>
      ) : null}
      </StepFormColumn>
    </div>
  )
}

export default connect((state) => ({
  language: state.App.language,
}))(injectIntl(PhoneModeV3))
