import { useMutation } from "@tanstack/react-query"
import authApi from "../../axios/auth"

const throwIfString = (result) => {
  if (typeof result === 'string') throw new Error(result)
  return result
}

export const useVerifyPolicyIdentityTypes = () => {
  return useMutation({
    mutationFn: (variables) =>
      authApi.verifyPolicyIdentityTypes(variables).then(throwIfString),
  })
}

export const useVerifyPolicyIdentitySession = () => {
  return useMutation({
    mutationFn: (variables) =>
      authApi.verifyPolicyIdentitySession(variables).then(throwIfString),
  })
}

export const useSendOtp = () => {
  return useMutation({
    mutationFn: ({ payload, languageCode }) =>
      authApi.sendOtp({ payload, languageCode }).then(throwIfString),
  })
}

export const useVerifyOtp = () => {
  return useMutation({
    mutationFn: (variables) =>
      authApi.verifyOtp(variables).then(throwIfString),
  })
}

export const useResendOTP = () => {
  return useMutation({
    mutationFn: (variables) =>
      authApi.resendOTP(variables).then(throwIfString),
  })
}
