import getAppConfig from '../../../../../components/utility/getAppConfig'
import { COLORS } from '../../../../../constants/colors'
import { getAssets } from '../../../../../helpers/utility'

function isPartnerHostname() {
  const { hostname } = window.location
  return (
    hostname.startsWith('mrt') ||
    hostname.includes('mkp') ||
    hostname.includes('ferizy') ||
    hostname.includes('ppibroker') ||
    hostname.includes('vnpt-msig')
  )
}

export function resolveLoginV3Theme() {
  const assets = getAssets()
  const configSecondary = getAppConfig('SECONDARY_COLOR', '')
  const configHighlighter = getAppConfig('HIGHLIGHTER_COLOR', '')

  let brand = configSecondary || COLORS.brandBlue
  if (!configSecondary && isPartnerHostname() && assets.headerBackgroundColor) {
    brand = assets.headerBackgroundColor
  }
  if (!configSecondary && window.location.hostname.includes('ppibroker')) {
    brand = COLORS.darkYellow
  }

  const accent =
    assets.landingPageTextHighlightColor || configHighlighter || brand
  const primaryBtn = configSecondary || brand
  const primaryHover = configHighlighter || primaryBtn

  return {
    brand,
    accent,
    primaryBtn,
    primaryHover,
  }
}

export function applyLoginV3Theme() {
  // const theme = resolveLoginV3Theme()
  const assets = getAssets()
  const root = document.documentElement

  root.style.setProperty('--login-v3-brand', COLORS.pasarPolisBLue)
  root.style.setProperty('--login-v3-accent', COLORS.pasarPolisBLue)
  root.style.setProperty('--login-v3-primary', COLORS.pasarPolisBLue)
  root.style.setProperty('--login-v3-primary-hover', COLORS.pasarPolisBLue)

  if (assets.landingPageTextHighlightColor) {
    root.style.setProperty(
      '--select-bg-color',
      assets.landingPageTextHighlightColor
    )
  }
  if (assets.headerTextColor) {
    root.style.setProperty('--select-text-color', assets.headerTextColor)
  }
  if (assets.loginTextHover) {
    root.style.setProperty('--text-hover-color', assets.loginTextHover)
  }
}
