export const DEFAULT_IDENTITY_CONFIG = {
  label: 'Nomor Identitas',
  fieldLabel: 'Nomor Identitas Pemegang Polis',
  headline: 'Masukkan Nomor Identitas untuk verifikasi data polis',
  subtitle: 'Hanya nomor identitas pemegang polis yang berlaku',
  minRawLength: 1,
  errorMessage: 'Nomor Identitas tidak boleh kosong',
  isDynamic: true,
}

export function stripMask(val) {
  return val.replace(/[\s._-]/g, '')
}

export function safeCompilePattern(pattern) {
  if (!pattern) return undefined
  try {
    return new RegExp(pattern)
  } catch {
    return undefined
  }
}

export function normalizeIdentityKey(value) {
  return String(value || '')
    .toUpperCase()
    .replace(/[\s-]+/g, '_')
}

export function normalizeFormLabelConfig(apiEntry) {
  if (apiEntry.fieldLabel) {
    return apiEntry
  }
  return {
    type: apiEntry.type,
    identityType: apiEntry.identity_type || apiEntry.identityType,
    label:
      apiEntry.label || apiEntry.login_word || DEFAULT_IDENTITY_CONFIG.label,
    fieldLabel: apiEntry.field_label || DEFAULT_IDENTITY_CONFIG.fieldLabel,
    headline: apiEntry.headline || DEFAULT_IDENTITY_CONFIG.headline,
    subtitle: apiEntry.subtitle || DEFAULT_IDENTITY_CONFIG.subtitle,
    minRawLength:
      apiEntry.min_raw_length ?? DEFAULT_IDENTITY_CONFIG.minRawLength,
    pattern: safeCompilePattern(apiEntry.pattern),
    errorMessage:
      apiEntry.error_message || DEFAULT_IDENTITY_CONFIG.errorMessage,
    isDynamic: true,
  }
}

export function normalizeFormLabelConfigs(entries = []) {
  return (entries || []).map(normalizeFormLabelConfig)
}

export function findFormLabelConfig(type, formLabelConfigs = []) {
  const key = normalizeIdentityKey(type)
  return (formLabelConfigs || []).find((entry) => {
    if (!entry) return false
    return (
      normalizeIdentityKey(entry.identity_type || entry.identityType) === key ||
      (entry.type && normalizeIdentityKey(entry.type) === key)
    )
  })
}

export function resolveIdentityConfig(type, formLabelConfigs = []) {
  const apiEntry = findFormLabelConfig(type, formLabelConfigs)
  if (apiEntry) {
    return normalizeFormLabelConfig(apiEntry)
  }

  const key = type.toUpperCase()
  if (key in identityTypeConfig) {
    return identityTypeConfig[key]
  }

  return { ...DEFAULT_IDENTITY_CONFIG }
}

export function getDefaultIdentityType(options) {
  if (!options || !options.length) return null
  const nikOption = options.find((t) => t.toUpperCase() === 'NIK')
  if (nikOption) return nikOption
  return options[0]
}

export function getIdentityHeadlineId(type) {
  return identityTypeConfig[type.toUpperCase()].headlineId
}

export function getIdentitySubtitleId(type) {
  return identityTypeConfig[type.toUpperCase()].subtitleId
}

export function getIdentityAccentLabelId(type) {
  return identityTypeConfig[type.toUpperCase()].label
}

export function getIdentityFieldLabelId(type) {
  return identityTypeConfig[type.toUpperCase()].fieldLabel
}

export function getIdentityTitleSuffixId() {
  return 'untuk verifikasi data polis'
}

export function formatDynamicMessage(intl, text) {
  if (!text) return text
  if (!intl || typeof intl.formatMessage !== 'function') return text
  return intl.formatMessage({ id: text, defaultMessage: text })
}

export function validateIdentityValue(type, raw, formLabelConfigs = []) {
  const cfg = resolveIdentityConfig(type, formLabelConfigs)
  if (!raw || raw.length < cfg.minRawLength) return cfg.errorMessage
  if (cfg.pattern && !cfg.pattern.test(raw)) return cfg.errorMessage
  return null
}
