import { useCallback, useState } from 'react'
import { useIntl } from 'react-intl'
import styled from 'styled-components'
import { Eye, EyeSlash } from '../../../../../../components/v2/icons'
import { ErrorText } from '../styles'

const Wrap = styled.div`
  margin-bottom: 0;
  width: 100%;
`

// Positioning context for the label and eye toggle. Must not include the error
// text, or their top: 50% resolves against the taller box and drifts down.
const Field = styled.div`
  position: relative;
  width: 100%;
`

const Input = styled.input`
  width: 100%;
  box-sizing: border-box;
  border: 2px solid ${(p) => (p.error ? '#ef4444' : '#e5e7eb')};
  border-radius: 12px;
  background: #fff;
  font-size: 16px;
  font-weight: 700;
  color: #333;
  padding: ${(p) =>
    p.floated ? '20px 48px 10px 20px' : '14px 48px 14px 20px'};

  &:focus {
    border-color: var(--login-v3-brand, #0180c8);
    outline: none;
  }

  &:disabled {
    opacity: 0.6;
  }
`

const Label = styled.label`
  position: absolute;
  left: 20px;
  pointer-events: none;
  font-family: Mulish, sans-serif;
  transition: all 0.2s ease;
  line-height: 20px;
  color: ${(p) => (p.floated ? '#333' : '#6b7280')};
  font-size: ${(p) => (p.floated ? '11px' : '16px')};
  font-weight: ${(p) => (p.floated ? 500 : 700)};
  top: ${(p) => (p.floated ? '10px' : '50%')};
  left: ${(p) => (p.floated ? '18px' : '20px')};
  transform: ${(p) => (p.floated ? 'none' : 'translateY(-50%)')};
  padding: 0 4px;
`

const ToggleBtn = styled.button`
  position: absolute;
  right: 16px;
  top: 50%;
  transform: translateY(-50%);
  display: inline-flex;
  align-items: center;
  justify-content: center;
  border: none;
  background: none;
  padding: 4px;
  color: #333;
  cursor: pointer;

  &:disabled {
    opacity: 0.5;
  }
`

const SecureFloatingInput = ({
  label,
  value,
  onChange,
  error = false,
  helperText = '',
  disabled = false,
}) => {
  const intl = useIntl()
  const [inputId] = useState(
    () => `secure-input-${Math.random().toString(36).slice(2, 9)}`
  )
  const [focused, setFocused] = useState(false)
  const [visible, setVisible] = useState(false)
  const floated = focused || value.length > 0

  const handleToggle = useCallback(() => {
    setVisible((v) => !v)
  }, [])

  const handleFocus = useCallback(() => setFocused(true), [])
  const handleBlur = useCallback(() => setFocused(false), [])
  const handleChange = useCallback((e) => onChange(e.target.value), [onChange])

  return (
    <Wrap data-testid="login-secure-input">
      <Field>
        <Input
          id={inputId}
          value={value}
          disabled={disabled}
          type={visible ? 'text' : 'password'}
          error={error}
          floated={floated}
          onFocus={handleFocus}
          onBlur={handleBlur}
          onChange={handleChange}
          aria-invalid={error}
        />
        <Label htmlFor={inputId} floated={floated}>
          {label}
        </Label>
        <ToggleBtn
          type="button"
          onClick={handleToggle}
          disabled={disabled}
          aria-label={intl.formatMessage({
            id: visible ? 'Sembunyikan' : 'Tampilkan',
          })}
        >
          {visible ? <Eye size={24} /> : <EyeSlash size={24} />}
        </ToggleBtn>
      </Field>
      {helperText ? <ErrorText>{helperText}</ErrorText> : null}
    </Wrap>
  )
}

export default SecureFloatingInput
