import { useState } from 'react'
import PropTypes from 'prop-types'
import InputMask from 'react-input-mask'
import {
  InputContainer,
  Label,
  Input,
  HelperText,
  PasswordToggle,
} from './styles'

const ViewOff = () => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    width="20"
    height="14"
    viewBox="0 0 24 24"
    fill="none"
  >
    <path
      d="M22 12C22 13.4 17.5556 19 12 19C6.44444 19 2 13.4 2 12C2 10.6 6.44444 5 12 5C17.5556 5 22 10.6 22 12Z"
      stroke="#333333"
      stroke-width="2"
    />
    <path
      d="M15.3334 12C15.3334 12.9283 14.9822 13.8185 14.3571 14.4749C13.732 15.1313 12.8841 15.5 12.0001 15.5C11.116 15.5 10.2682 15.1313 9.64306 14.4749C9.01794 13.8185 8.66675 12.9283 8.66675 12C8.66675 11.0717 9.01794 10.1815 9.64306 9.52513C10.2682 8.86875 11.116 8.5 12.0001 8.5C12.8841 8.5 13.732 8.86875 14.3571 9.52513C14.9822 10.1815 15.3334 11.0717 15.3334 12Z"
      stroke="#333333"
      stroke-width="2"
    />
    <path
      d="M2 19L22 5"
      stroke="#333333"
      stroke-width="2"
      stroke-linecap="round"
    />
  </svg>
)

const ViewOn = () => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    width="20"
    height="14"
    viewBox="0 0 24 24"
    fill="none"
  >
    <path
      d="M22 12C22 13.4 17.5556 19 12 19C6.44444 19 2 13.4 2 12C2 10.6 6.44444 5 12 5C17.5556 5 22 10.6 22 12Z"
      stroke="#333333"
      stroke-width="2"
    />
    <path
      d="M15.3334 12C15.3334 12.9283 14.9822 13.8185 14.3571 14.4749C13.732 15.1313 12.8841 15.5 12.0001 15.5C11.116 15.5 10.2682 15.1313 9.64306 14.4749C9.01794 13.8185 8.66675 12.9283 8.66675 12C8.66675 11.0717 9.01794 10.1815 9.64306 9.52513C10.2682 8.86875 11.116 8.5 12.0001 8.5C12.8841 8.5 13.732 8.86875 14.3571 9.52513C14.9822 10.1815 15.3334 11.0717 15.3334 12Z"
      stroke="#333333"
      stroke-width="2"
    />
  </svg>
)

const TextInput = ({
  label,
  value,
  onChange,
  type = 'text',
  error = false,
  helperText = '',
  disabled = false,
  readOnly = false,
  autoFocus = false,
  mask,
  compact = false,
  ...props
}) => {
  const [isPasswordVisible, setIsPasswordVisible] = useState(false)
  const [isFocused, setIsFocused] = useState(false)

  const isValueNotEmpty = value !== '' && value !== undefined && value !== null

  const handleTogglePassword = () => {
    setIsPasswordVisible(!isPasswordVisible)
  }

  const handleFocus = () => {
    setIsFocused(true)
  }

  const handleBlur = () => {
    setIsFocused(false)
  }

  const handleChange = (e) => {
    const newValue = e.target.value
    onChange(newValue)
  }

  const isLabelFloated = isValueNotEmpty || isFocused
  const labelColor = isLabelFloated ? (error ? '#ef4444' : '#333') : null

  const isPasswordType = type === 'password'
  const effectiveType =
    isPasswordType && !isPasswordVisible ? 'password' : 'text'

  const inputId = label.toLowerCase().replace(/\s+/g, '-')

  return (
    <InputContainer compact={compact}>
      {mask ? (
        <InputMask
          mask={mask}
          value={value}
          onChange={handleChange}
          disabled={disabled}
          readOnly={readOnly}
          onFocus={handleFocus}
          onBlur={handleBlur}
        >
          {(inputProps) => (
            <Input
              id={inputId}
              type={effectiveType}
              autoFocus={autoFocus}
              aria-invalid={error}
              isPasswordType={isPasswordType}
              {...inputProps}
              {...props}
            />
          )}
        </InputMask>
      ) : (
        <Input
          id={inputId}
          type={effectiveType}
          value={value}
          onChange={handleChange}
          onFocus={handleFocus}
          onBlur={handleBlur}
          disabled={disabled}
          readOnly={readOnly}
          autoFocus={autoFocus}
          aria-invalid={error}
          isPasswordType={isPasswordType}
          {...props}
        />
      )}
      <Label
        htmlFor={inputId}
        isLabelFloated={isLabelFloated}
        labelColor={labelColor}
      >
        {label}
      </Label>
      {isPasswordType && (
        <PasswordToggle
          onClick={handleTogglePassword}
          title={isPasswordVisible ? 'Hide password' : 'Show password'}
          aria-label={isPasswordVisible ? 'Hide password' : 'Show password'}
        >
          {isPasswordVisible ? <ViewOff /> : <ViewOn />}
        </PasswordToggle>
      )}
      {helperText || error ? (
        <HelperText error={error}>{helperText}</HelperText>
      ) : null}
    </InputContainer>
  )
}

TextInput.propTypes = {
  label: PropTypes.string.isRequired,
  value: PropTypes.oneOfType([PropTypes.string, PropTypes.number]),
  onChange: PropTypes.func.isRequired,
  type: PropTypes.oneOf(['text', 'password', 'email', 'number', 'tel']),
  error: PropTypes.bool,
  helperText: PropTypes.string,
  disabled: PropTypes.bool,
  readOnly: PropTypes.bool,
  autoFocus: PropTypes.bool,
  mask: PropTypes.string,
  compact: PropTypes.bool,
}

TextInput.defaultProps = {
  value: '',
  onChange: () => {},
  type: 'text',
  error: false,
  helperText: '',
  disabled: false,
  readOnly: false,
  autoFocus: false,
  mask: undefined,
  compact: false,
}

export default TextInput
