import { useCallback, useEffect, useRef, useState } from 'react'
import { FormattedMessage, injectIntl } from 'react-intl'
import {
  PrimaryBtn,
  PrimaryBtnText,
} from '../../../../../../components/v2/Button'
import {
  ErrorText,
  OtpBackLink,
  OtpBox,
  OtpResendWrap,
  OtpRow,
  OtpSection,
  OtpSpinner,
  OtpStatusLine,
  OtpSubtitle,
  OtpTitle,
  StepFormColumn,
} from '../styles'

const OTP_LENGTH = 6

function formatCountdown(seconds) {
  const m = Math.floor(seconds / 60)
  const s = seconds % 60
  return `${String(m).padStart(2, '0')}:${String(s).padStart(2, '0')}`
}

function OtpModeV3({
  phone,
  country,
  loading,
  onVerifyOtp,
  onResendOtp,
  onBackToPhone,
  intl,
}) {
  const [otpValues, setOtpValues] = useState(Array(OTP_LENGTH).fill(''))
  const [otpError, setOtpError] = useState('')
  const [countdown, setCountdown] = useState(60)
  const otpRefs = useRef([])

  useEffect(() => {
    const t = setInterval(() => setCountdown((c) => (c <= 0 ? 0 : c - 1)), 1000)
    return () => clearInterval(t)
  }, [])

  useEffect(() => {
    setTimeout(() => {
      const firstInput = otpRefs.current[0]
      if (firstInput) firstInput.focus()
    }, 0)
  }, [])

  const focusFirst = useCallback(() => {
    const firstInput = otpRefs.current[0]
    if (firstInput) firstInput.focus()
  }, [])

  const handleVerify = useCallback(
    (code) => {
      const otpCode = code != null ? code : otpValues.join('')
      if (otpCode.length !== OTP_LENGTH) return
      setOtpError('')
      onVerifyOtp(otpCode, () => {
        setOtpError(
          intl.formatMessage({ id: 'Kode OTP salah, silakan coba lagi' })
        )
        setOtpValues(Array(OTP_LENGTH).fill(''))
        setTimeout(focusFirst, 0)
      })
    },
    [otpValues, onVerifyOtp, intl, focusFirst]
  )

  const handleChange = useCallback(
    (index, value) => {
      if (loading) return
      const digit = value.replace(/\D/g, '').slice(-1)
      const next = [...otpValues]
      next[index] = digit
      setOtpValues(next)
      setOtpError('')
      if (digit && index < OTP_LENGTH - 1) {
        const nextInput = otpRefs.current[index + 1]
        if (nextInput) nextInput.focus()
      }
      if (next.join('').length === OTP_LENGTH) handleVerify(next.join(''))
    },
    [otpValues, handleVerify, loading]
  )

  const handlePaste = useCallback(
    (e) => {
      if (loading) return
      e.preventDefault()
      const pasted = e.clipboardData
        .getData('text')
        .replace(/\D/g, '')
        .slice(0, OTP_LENGTH)
      if (!pasted) return
      const next = Array(OTP_LENGTH).fill('')
      for (let i = 0; i < pasted.length; i++) next[i] = pasted[i]
      setOtpValues(next)
      setOtpError('')
      if (pasted.length === OTP_LENGTH) handleVerify(pasted)
    },
    [handleVerify, loading]
  )

  const handleResend = useCallback(() => {
    if (loading) return
    setCountdown(60)
    setOtpValues(Array(OTP_LENGTH).fill(''))
    setOtpError('')
    onResendOtp((error) => {
      if (error) setOtpError(error)
      focusFirst()
    })
  }, [onResendOtp, loading, focusFirst])

  const handleKeyDown = useCallback((index, digit, e) => {
    if (e.key === 'Backspace' && !digit && index > 0) {
      const prevInput = otpRefs.current[index - 1]
      if (prevInput) prevInput.focus()
    }
  }, [])

  return (
    <div data-testid="login-otp-mode">
      <StepFormColumn>
      <div style={{ paddingBottom: 16 }}>
        <OtpTitle data-testid="login-otp-title">
          <FormattedMessage id="Masukkan" />{' '}
          <FormattedMessage id="Nomor OTP" />{' '}
          <FormattedMessage id="yang terkirim ke nomor" />{' '}
          <span className="phone">{`+${country.value} ${phone}`}</span>
        </OtpTitle>
        <OtpSubtitle>
          (
          <FormattedMessage id="Hanya nomor ponsel pemegang polis yang berlaku" />
          )
        </OtpSubtitle>
      </div>

      <OtpSection>
        <OtpRow onPaste={handlePaste}>
          {otpValues.map((digit, index) => (
            <OtpBox
              key={index}
              ref={(el) => {
                otpRefs.current[index] = el
              }}
              inputMode="numeric"
              maxLength={1}
              value={digit}
              error={!!otpError}
              disabled={loading}
              onChange={(e) => handleChange(index, e.target.value)}
              onKeyDown={(e) => handleKeyDown(index, digit, e)}
            />
          ))}
        </OtpRow>
        {otpError ? <ErrorText>{otpError}</ErrorText> : null}

        {loading ? (
          <OtpStatusLine data-testid="login-otp-verifying">
            <OtpSpinner />
            <FormattedMessage id="Memverifikasi..." />
          </OtpStatusLine>
        ) : countdown > 0 ? (
          <OtpStatusLine>
            <FormattedMessage id="Kirim ulang OTP dalam" />{' '}
            <span className="countdown-time">{formatCountdown(countdown)}</span>
          </OtpStatusLine>
        ) : (
          <OtpResendWrap>
            <PrimaryBtn
              onClick={handleResend}
              disabled={loading}
              data-testid="login-otp-resend"
            >
              <PrimaryBtnText>
                <FormattedMessage id="Kirim Ulang OTP" />
              </PrimaryBtnText>
            </PrimaryBtn>
          </OtpResendWrap>
        )}

        <OtpBackLink
          type="button"
          onClick={onBackToPhone}
          disabled={loading}
          data-testid="login-otp-back-phone"
        >
          <FormattedMessage id="Ubah Nomor Ponsel" />
        </OtpBackLink>
      </OtpSection>
      </StepFormColumn>
    </div>
  )
}

export default injectIntl(OtpModeV3)
