import { partnerClaimPath } from './partner'

export function resolvePostLoginRedirect(params) {
  if (params.internalId && params.identitySource) {
    const isAgency =
      params.isAgentPolicy === true ||
      params.isAgentPolicy === 'true' ||
      params.identitySource === 'agency-policy'
    return `/policydetail/${params.internalId}?source=${params.identitySource}&isAgency=${isAgency}`
  }

  if (params.claimsInternalId) {
    return `/claimdetail/${params.claimsInternalId}`
  }

  if (params.savedRedirect) {
    return params.savedRedirect
  }

  if (params.locationStateFrom) {
    return params.locationStateFrom
  }

  if (params.partnerOrigin) {
    const path = partnerClaimPath(params.partnerOrigin)
    if (path) return path
  }

  return '/'
}
