import { Card, CardShell, CardWrap, TabSlot } from '../styles'

export function LoginV3Card({ tabs, children }) {
  const hasTabs = Boolean(tabs)

  return (
    <CardWrap className="login-v3-wrap">
      <CardShell hasTabs={hasTabs}>
        {hasTabs ? <TabSlot>{tabs}</TabSlot> : null}
        <Card
          className="login-v3-card"
          data-testid="login-card"
          hasTabs={hasTabs}
        >
          {children}
        </Card>
      </CardShell>
    </CardWrap>
  )
}
