import React, { Component } from 'react'
import { Redirect } from 'react-router-dom'

import { connect } from 'react-redux'
import { Row, Col, Form } from 'antd'
import Chatbot from '@pasarpolis/ava-chatbot'
import authAction from '../../../redux/auth/actions'
import SignInStyleWrapper from './index.style'
// import Footer from '../../../components/Footer/footer'
import { get } from 'lodash'

import { injectIntl } from 'react-intl'
import { RESEND_OTP_COUNT_DOWN } from '../../../constants/constants'
import { getAssets } from '../../../helpers/utility'
import getDocumentReferrer from '../../../helpers/getDocumentReferrer'
import isTrustedDomain from '../../../helpers/isTrustedDomain'
import LoginFormV3 from '../components/LoginForm/v3'
import LoginMarketingHero from '../components/LoginForm/v3/components/LoginMarketingHero'
import { applyLoginV3Theme } from '../components/LoginForm/v3/login-theme'
import { HOME_BANNER, MOBILE_HOME_BANNER } from '../../../constants/icons'
// import AvaPopup from '../../../components/AvaPopup'

const { login } = authAction

class SignIn extends Component {
  constructor(props) {
    super(props)
    this.state = {
      visible: false,
      from: '/',
      verifyBox: false,
      stopwatch: RESEND_OTP_COUNT_DOWN,
      phoneverify: '',
      operationId: window.sessionStorage.getItem('operationId') || '',
    }
    this.decrementer = null
    this.resendCount = window.sessionStorage.getItem('count') || 0
    this.redirectFired = false
  }
  componentDidMount() {
    // console.log(this.props.language?.locale === 'id')
    window.scrollTo(0, 0)
    applyLoginV3Theme()
    if (this.props.isLoggedIn && !this.redirectFired) {
      this.redirectFired = true
      const redirectFrom = this.getRedirectFrom()
      this.redirectionHandler(redirectFrom)
    }
  }
  componentWillReceiveProps(nextProps) {
    const { operationId: propsOperationId } = nextProps
    const { operationId: stateOperationId } = this.state
    const locationState = this.props.history.location.state || {}
    const from = locationState.from || {}
    const fromPathname = from.pathname || from

    if (Object.keys(from).length > 0) {
      this.setState({
        from: fromPathname,
      })
    }

    if (propsOperationId !== '' && propsOperationId !== stateOperationId) {
      this.setState({
        operationId: propsOperationId,
        verifyBox: true,
      })
    }
  }
  componentDidUpdate(prevProps) {
    applyLoginV3Theme()
    if (this.state.stopwatch < 1) {
      clearInterval(this.decrementer)
    }
    if (this.props.isLoggedIn && !prevProps.isLoggedIn && !this.redirectFired) {
      this.redirectFired = true
      const redirectFrom = this.getRedirectFrom()
      this.redirectionHandler(redirectFrom)
    }
  }
  componentWillUnmount() {
    window.removeEventListener('resize', this.updateDimensions)
    // clear the interval as component remove from the dom
    window.sessionStorage.setItem('count', 300)
    clearInterval(this.decrementer)
  }

  getRedirectFrom = () => {
    const internalId = window.sessionStorage.getItem('internal_id')
    const sourcePolicy = window.localStorage.getItem('source')
    const claimsInternalId = window.sessionStorage.getItem('claims_internal_id')
    const isAgentPolicy = window.localStorage.getItem('is_agent_policy')
    const savedRedirect = window.localStorage.getItem('logout_redirect')

    let resolvedInternalId = internalId
    let savedSearch = ''

    if (!resolvedInternalId && savedRedirect) {
      const match = savedRedirect.match(/^\/policydetail\/([^?]+)(\?.*)?$/)
      if (match) {
        resolvedInternalId = match[1]
        savedSearch = match[2] || ''
      }
    }

    let isFrom = { pathname: '/' }
    if (resolvedInternalId) {
      const search =
        savedSearch || `?source=${sourcePolicy}&isAgency=${isAgentPolicy}`
      isFrom = { pathname: `/policydetail/${resolvedInternalId}`, search }
    }
    if (claimsInternalId) {
      isFrom = { pathname: `/claimdetail/${claimsInternalId}` }
    }

    const hasFreshOtp = window.localStorage.getItem('source')
    return hasFreshOtp ? isFrom : get(this.props.location, 'state.from', isFrom)
  }

  redirectionHandler = (from) => {
    const { history, location } = this.props
    const urlObj = getDocumentReferrer()
    if (
      urlObj.pathname &&
      urlObj.pathname.includes('/endorsement') &&
      isTrustedDomain(urlObj.host)
    ) {
      window.location.href = urlObj.href
    } else {
      const fromPath = typeof from === 'string' ? from : from.pathname
      if (fromPath === '/' || !fromPath) {
        history.replace('/')
        return
      }
      const redirectTo =
        typeof from === 'string'
          ? {
              pathname: from.split('?')[0],
              search: from.includes('?')
                ? `?${from.split('?')[1]}`
                : location.search,
            }
          : { pathname: from.pathname, search: from.search || location.search }

      const localSource = window.localStorage.getItem('source')
      if (localSource && redirectTo.pathname.startsWith('/policydetail/')) {
        const params = new URLSearchParams(redirectTo.search || '')
        params.set('source', localSource)
        const localIsAgency = window.localStorage.getItem('is_agent_policy')
        if (localIsAgency !== null) {
          params.set('isAgency', localIsAgency)
        }
        redirectTo.search = params.toString() ? `?${params.toString()}` : ''
      }

      history.replace(redirectTo)
    }
  }

  renderDesktopView() {
    const { phoneOnly } = this.props
    return (
      <SignInStyleWrapper desktop>
        <div className="generic-otp__container">
          <Row type="flex" justify="center" className="generic-otp__content">
            <Col xs={24} sm={24} md={22} lg={22} xl={22}>
              <LoginMarketingHero />
              <LoginFormV3 phoneOnly={phoneOnly} />
            </Col>
          </Row>
          <div className="generic-otp__banner-wrap">
            <picture>
              <source
                media="(max-width: 768px)"
                srcSet={getAssets().mobileHomeBanner || MOBILE_HOME_BANNER}
              />
              <img
                className="generic-otp__banner"
                src={getAssets().homeBanner || HOME_BANNER}
                alt=""
              />
            </picture>
          </div>
          <div className="generic-otp__footer-wrap">{getAssets().footer}</div>
        </div>
      </SignInStyleWrapper>
    )
  }

  render() {
    if (this.props.isLoggedIn) {
      return <Redirect to={this.getRedirectFrom()} />
    }
    return (
      <React.Fragment>
        {
          this.renderDesktopView()
        }
        {/* <AvaPopup locale={this.props.language?.locale} />*/}
        {/* {this.props.language && this.props.language?.locale === 'id' && getAssets().showAvaPopup && (
          <Chatbot partner={this.props.partner} />
        )}*/}
      </React.Fragment>
    )
  }
}
const WrappedDSigninCardForm = Form.create()(injectIntl(SignIn))
export default connect(
  (state) => ({
    partner: state.App.partner,
    isLoggedIn: state.Auth.authStatus,
    operationId: state.Auth.operationId,
    isWhatsAppLogin: state.Auth.isWhatsAppLogin,
    language: state.App.language,
    countryCode: state.Auth.countryCode,
  }),
  {
    login,
  }
)(WrappedDSigninCardForm)
