export function LoginTabSwitcher({
  activeTab,
  onTabChange,
  showClaimStatusTab,
}) {
  if (!showClaimStatusTab) return null

  return (
    <TabBar className="login-v3-tabs" data-testid="login-tab-switcher">
      <TabButton
        type="button"
        active={activeTab === 'submit'}
        onClick={() => onTabChange('submit')}
        data-testid="login-tab-submit"
      >
        <AjukanKlaimIcon />
        <FormattedMessage id="Ajukan Klaim" />
      </TabButton>
      <TabButton
        type="button"
        active={activeTab === 'status'}
        onClick={() => onTabChange('status')}
        data-testid="login-tab-status"
      >
        <CekStatusIcon />
        <FormattedMessage id="Cek Status Klaim" />
      </TabButton>
    </TabBar>
  )
}
