const PARTNER_FROM_PATHS = {
  '/gojek-passenger/claim': 'gojek',
  '/go-passenger/claim': 'gojek',
  '/go-driver/claim': 'godriver',
  '/go-life/claim': 'golife',
}

const PARTNER_CLAIM_PATHS = {
  gojek: '/gojek-passenger/claim',
  godriver: '/go-driver/claim',
  golife: '/go-life/claim',
}

const PHONE_ONLY_FROM_PATHS = new Set(Object.keys(PARTNER_FROM_PATHS))

export function detectPartnerOrigin(from) {
  if (!from) return null
  return PARTNER_FROM_PATHS[from] || null
}

export function isPhoneOnlyFrom(from) {
  return from != null && PHONE_ONLY_FROM_PATHS.has(from)
}

export function partnerClaimPath(origin) {
  if (!origin) return null
  return PARTNER_CLAIM_PATHS[origin] || null
}
