import { COUNTRY_CODES } from '../../../../../constants/constants'

export function getDefaultCountry(locale) {
  const map = { id: '62', vi: '84', th: '66' }
  const dial = map[locale] || '62'
  return (
    COUNTRY_CODES.find((c) => c.value === dial) ||
    COUNTRY_CODES.find((c) => c.countryCode === 'ID')
  )
}

export function formatPhoneForApi(country, nationalNumber) {
  return `${country.value}-${nationalNumber}`
}

export { COUNTRY_CODES }
