import { connect } from 'react-redux'
import { FormattedMessage } from 'react-intl'
import { LOGIN_V3_HERO_MESSAGE_ID } from '../constants'
import { HeroText, HeroWrap } from '../styles'

function LoginMarketingHero({ highlightColor }) {
  return (
    <HeroWrap data-testid="login-marketing-hero">
      <HeroText>
        <FormattedMessage
          id={LOGIN_V3_HERO_MESSAGE_ID}
          defaultMessage={LOGIN_V3_HERO_MESSAGE_ID}
          values={{
            highlight: (chunks) => (
              <span style={{ color: highlightColor }}>{chunks}</span>
            ),
          }}
        />
      </HeroText>
    </HeroWrap>
  )
}

export default connect(() => ({
  highlightColor: 'var(--login-v3-accent, #0180c8)',
}))(LoginMarketingHero)
