import { useCallback, useState } from 'react'
import { FormattedMessage } from 'react-intl'
import { CheckboxOff, CheckboxOn } from '../../../../../../components/v2/icons'
import { CheckboxLabel } from '../../../../../../components/v2/Checkbox'
import { FooterCheckboxRow } from '../styles'
import TermAndConditionModal from '../../../../../../components/TermAndConditionModal'

export function TermsCheckbox({ checked, onToggle, disabled, inline }) {
  const [isTermsOpen, setTermsOpen] = useState(false)

  const handleOpenTerms = useCallback((e) => {
    e.stopPropagation()
    setTermsOpen(true)
  }, [])

  const handleCloseTerms = useCallback(() => setTermsOpen(false), [])

  return (
    <>
      <FooterCheckboxRow
        data-testid="login-terms-toggle"
        onClick={onToggle}
        className={inline ? undefined : 'login-v3-terms-spaced'}
      >
        {checked ? <CheckboxOn /> : <CheckboxOff />}
        <CheckboxLabel>
          <FormattedMessage id="Saya setuju" />
          <span className="link" onClick={handleOpenTerms}>
            {' '}
            <FormattedMessage id="Syarat & Ketentuan" />{' '}
          </span>
          <FormattedMessage id="yang berlaku" />
        </CheckboxLabel>
      </FooterCheckboxRow>
      <TermAndConditionModal isOpen={isTermsOpen} onClose={handleCloseTerms} />
    </>
  )
}
