import { LoginV3Card } from './LoginV3Card'
import { LoginTabSwitcher } from './LoginTabSwitcher'
import { CheckStatusPanel } from './CheckStatusPanel'
import { SubmitClaimPanel } from './SubmitClaimPanel'

export function LoginV3Shell({ config, flow, locale }) {
  const tabs = config.showClaimStatusTab ? (
    <LoginTabSwitcher
      activeTab={flow.loginTab}
      onTabChange={(tab) => {
        flow.setLoginTab(tab)
        if (tab === 'submit') {
          flow.setAuthPath(config.phoneOnly ? 'phone' : 'policy')
        } else {
          flow.setStatusPath('claim-number')
        }
      }}
      showClaimStatusTab={config.showClaimStatusTab}
    />
  ) : null

  return (
    <LoginV3Card tabs={tabs}>
      {flow.loginTab === 'status' && config.showClaimStatusTab ? (
        <CheckStatusPanel flow={flow} />
      ) : (
        <SubmitClaimPanel config={config} flow={flow} locale={locale} />
      )}
    </LoginV3Card>
  )
}
