import { useCallback, useState } from 'react'
import { FormattedMessage, injectIntl } from 'react-intl'
import TextInput from '../../../../../../components/v2/TextInput'
import {
  PrimaryBtn,
  PrimaryBtnText,
  Spinner,
} from '../../../../../../components/v2/Button'
import { useVerifyPolicyIdentityTypes } from '../../../../../../request/query/auth'
import {
  InlineFieldAction,
  InlineFieldGrow,
  InlineFieldRow,
} from './InlineFieldRow'
import { LoginV3SecondaryButton } from './LoginV3SecondaryButton'
import { ModeDivider } from './ModeDivider'
import { ErrorText, HintText, PolicyStepHeader, SectionSubtitle, SectionTitle, StepFormColumn } from '../styles'

function PolicyNumberPanel({ onComplete, onSwitchToPhone, intl }) {
  const [policyNumber, setPolicyNumber] = useState('')
  const [error, setError] = useState('')
  const { mutate, isLoading } = useVerifyPolicyIdentityTypes()

  const handleChange = useCallback((value) => {
    setPolicyNumber(value)
    setError('')
  }, [])

  const handleNext = useCallback(() => {
    if (!policyNumber.trim()) return

    mutate(
      { policy_number: policyNumber },
      {
        onSuccess: (response) => {
          const data = (response && response.data) || {}
          const types = data.identity_types || []
          const formLabelConfigs = data.form_label_configs || []
          setError('')
          onComplete(policyNumber, '', types, formLabelConfigs)
        },
        onError: (err) => {
          setError(
            (err && err.message) ||
              intl.formatMessage({ id: 'Nomor polis tidak ditemukan' })
          )
        },
      }
    )
  }, [policyNumber, intl, mutate, onComplete])

  const canSubmit = policyNumber.trim().length > 0

  return (
    <div data-testid="login-step-policy">
      <PolicyStepHeader>
        <SectionTitle>
          <FormattedMessage id="Masukkan" />
          <span className="accent">
            {' '}
            <FormattedMessage id="Nomor Polis" />{' '}
          </span>
          <FormattedMessage id="untuk melakukan pengajuan klaim" />
        </SectionTitle>
        <SectionSubtitle>
          (
          <FormattedMessage id="Nomor polis dapat dilihat pada sertifikat polis atau e-polis Anda" />
          )
        </SectionSubtitle>
      </PolicyStepHeader>

      <StepFormColumn>
      <InlineFieldRow stacked>
        <InlineFieldGrow>
          <TextInput
            label={intl.formatMessage({ id: 'Nomor Polis' })}
            value={policyNumber}
            onChange={handleChange}
            error={!!error}
            disabled={isLoading}
            compact
          />
          {error ? (
            <ErrorText>{error}</ErrorText>
          ) : (
            <HintText>
              <FormattedMessage id="Contoh: 1012100109988 atau AGS-88991230" />
            </HintText>
          )}
        </InlineFieldGrow>
        <InlineFieldAction>
          <PrimaryBtn
            onClick={handleNext}
            disabled={isLoading || !canSubmit}
            className={!canSubmit ? 'login-v3-btn-disabled' : ''}
          >
            {isLoading && <Spinner />}
            <PrimaryBtnText>
              <FormattedMessage id="Mulai" />
            </PrimaryBtnText>
          </PrimaryBtn>
        </InlineFieldAction>
      </InlineFieldRow>

      <ModeDivider />
      <LoginV3SecondaryButton
        onClick={onSwitchToPhone}
        testId="login-skip-phone"
      >
        <FormattedMessage id="Masuk Menggunakan Nomor Telepon" />
      </LoginV3SecondaryButton>
      </StepFormColumn>
    </div>
  )
}

export default injectIntl(PolicyNumberPanel)
