import { useCallback } from 'react'
import { FormattedMessage } from 'react-intl'
import { BackArrow } from '../../../../../../components/v2/icons'
import { BackPolicyBtn, BackStartBtn, FooterBackRow } from '../styles'

function IdentityBackFooter({ onBack, disabled, backLabelId }) {
  const handleBackStart = useCallback(() => {
    if (onBack) onBack()
  }, [onBack])

  const handleBackPolicy = useCallback(() => {
    if (onBack) onBack()
  }, [onBack])

  return (
    <FooterBackRow>
      <BackStartBtn
        type="button"
        onClick={handleBackStart}
        disabled={disabled}
        data-testid="login-back-to-start"
      >
        <BackArrow />
        <FormattedMessage id="Kembali ke awal" />
      </BackStartBtn>
      <BackPolicyBtn
        type="button"
        onClick={handleBackPolicy}
        disabled={disabled}
        data-testid="login-identity-back"
      >
        <FormattedMessage id={backLabelId} />
      </BackPolicyBtn>
    </FooterBackRow>
  )
}

export default IdentityBackFooter
