import { detectPartnerOrigin, isPhoneOnlyFrom } from './partner'

function resolveShowClaimStatusTab() {
  return process.env.REACT_APP_LOGIN_SHOW_CLAIM_STATUS_TAB === 'true'
}

function resolveFromState(state) {
  if (!state || !state.from) return null
  if (typeof state.from === 'string') return state.from
  return state.from.pathname || null
}

export function resolveLoginEntry(
  searchParams,
  locationState,
  pathname,
  phoneOnlyOverride
) {
  const fromParam = searchParams.get('from')
  const stateFrom = resolveFromState(locationState)
  const from = fromParam || stateFrom
  const phoneOnlyParam = searchParams.get('phoneOnly') === 'true'
  const partnerOrigin = detectPartnerOrigin(from)
  const phoneOnly =
    phoneOnlyOverride != null
      ? phoneOnlyOverride
      : phoneOnlyParam || isPhoneOnlyFrom(from)

  const whiteLabelMatch = pathname && pathname.match(/^\/([^/]+)$/)
  const reserved = new Set(['login', 'policydetail', 'claimdetail', 'check-status'])
  const productSlug =
    whiteLabelMatch && whiteLabelMatch[1] ? whiteLabelMatch[1] : null
  const isWhiteLabel =
    productSlug != null &&
    !reserved.has(productSlug) &&
    !productSlug.includes('.')

  if (isWhiteLabel) {
    return {
      variant: 'white-label',
      phoneOnly: true,
      partnerOrigin: null,
      requireCaptcha: false,
      showClaimStatusTab: resolveShowClaimStatusTab(),
    }
  }

  if (phoneOnly) {
    return {
      variant: 'phone-only',
      phoneOnly: true,
      partnerOrigin,
      requireCaptcha: true,
      showClaimStatusTab: resolveShowClaimStatusTab(),
    }
  }

  return {
    variant: 'standard',
    phoneOnly: false,
    partnerOrigin: null,
    requireCaptcha: true,
    showClaimStatusTab: resolveShowClaimStatusTab(),
  }
}
