import { connect } from 'react-redux'
import { useLocation } from 'react-router-dom'
import { resolveLoginEntry } from './login-entry'
import { useLoginFlow } from './hooks/useLoginFlow'
import { LoginV3Shell } from './components/LoginV3Shell'

function LoginFormV3({ phoneOnly, language }) {
  const location = useLocation()
  const searchParams = new URLSearchParams(location.search)
  const config = resolveLoginEntry(
    searchParams,
    location.state,
    location.pathname,
    phoneOnly
  )
  const flow = useLoginFlow(config)

  return (
    <LoginV3Shell
      config={config}
      flow={flow}
      locale={(language && language.locale) || 'id'}
    />
  )
}

export default connect((state) => ({
  language: state.App.language,
}))(LoginFormV3)
