import { InlineAction, InlineGrow, InlineRow } from '../styles'

export function InlineFieldRow({ className, stacked, children }) {
  const rowClassName = [stacked && 'stacked', className].filter(Boolean).join(' ')
  return <InlineRow className={rowClassName || undefined}>{children}</InlineRow>
}

export function InlineFieldGrow({ children }) {
  return <InlineGrow>{children}</InlineGrow>
}

export function InlineFieldAction({ children }) {
  return <InlineAction>{children}</InlineAction>
}
