import { useCallback, useEffect, useMemo, useRef, useState } from 'react'
import { FormattedMessage, injectIntl } from 'react-intl'
import {
  PrimaryBtn,
  PrimaryBtnText,
  Spinner,
} from '../../../../../../components/v2/Button'
import {
  formatDynamicMessage,
  getDefaultIdentityType,
  getIdentityAccentLabelId,
  getIdentityFieldLabelId,
  getIdentitySubtitleId,
  getIdentityTitleSuffixId,
  resolveIdentityConfig,
  stripMask,
  validateIdentityValue,
} from '../identity-config'
import SecureFloatingInput from './SecureFloatingInput'
import IdentityBackFooter from './IdentityBackFooter'
import { TermsCheckbox } from './TermsCheckbox'
import {
  DropdownItem,
  DropdownList,
  FieldStack,
  IdentityContextLine,
  IdentityHeader,
  SectionSubtitle,
  SectionTitle,
  StepFormColumn,
  TypeDropdownBtn,
} from '../styles'

function IdentityVerifyPanel({
  identityOptions,
  formLabelConfigs = [],
  contextNumber = '',
  loading,
  serverError,
  onClearServerError,
  backLabelId,
  onBack,
  onVerify,
  onStubVerify,
  intl,
}) {
  const [identityNumber, setIdentityNumber] = useState('')
  const [checked, setChecked] = useState(false)
  const [errors, setErrors] = useState({})
  const [selectedType, setSelectedType] = useState(() =>
    getDefaultIdentityType(identityOptions)
  )
  const [dropdownOpen, setDropdownOpen] = useState(false)
  const dropdownRef = useRef(null)

  const cfg = useMemo(
    () =>
      selectedType
        ? resolveIdentityConfig(selectedType, formLabelConfigs)
        : null,
    [selectedType, formLabelConfigs]
  )
  const hasMultiple = identityOptions && identityOptions.length > 1

  const getTypeLabel = useCallback(
    (type) => {
      const typeCfg = resolveIdentityConfig(type, formLabelConfigs)
      return typeCfg.isDynamic
        ? formatDynamicMessage(intl, typeCfg.label)
        : typeCfg.label
    },
    [formLabelConfigs, intl]
  )

  useEffect(() => {
    setSelectedType(getDefaultIdentityType(identityOptions))
    setIdentityNumber('')
    setErrors({})
  }, [identityOptions])

  useEffect(() => {
    const onClick = (e) => {
      if (dropdownRef.current && !dropdownRef.current.contains(e.target)) {
        setDropdownOpen(false)
      }
    }
    if (dropdownOpen) document.addEventListener('mousedown', onClick)
    return () => document.removeEventListener('mousedown', onClick)
  }, [dropdownOpen])

  const handleToggleChecked = useCallback(() => {
    if (!loading) setChecked((v) => !v)
  }, [loading])

  const handleIdentityChange = useCallback(
    (value) => {
      setIdentityNumber(value)
      setErrors((prev) => ({ ...prev, identity: undefined }))
      if (serverError && onClearServerError) onClearServerError()
    },
    [serverError, onClearServerError]
  )

  const handleVerify = useCallback(() => {
    if (!selectedType || !cfg) return
    const trimmed = identityNumber.trim()
    const raw = stripMask(trimmed)
    if (!raw || !checked) return
    const identityError = validateIdentityValue(
      selectedType,
      raw,
      formLabelConfigs
    )
    if (identityError) {
      setErrors({
        identity: cfg.isDynamic
          ? formatDynamicMessage(intl, identityError)
          : intl.formatMessage({ id: identityError }),
      })
      return
    }
    setErrors({})
    if (onStubVerify) {
      onStubVerify()
      return
    }
    onVerify(selectedType, trimmed)
  }, [
    selectedType,
    cfg,
    identityNumber,
    checked,
    intl,
    onVerify,
    onStubVerify,
    formLabelConfigs,
  ])

  const handleTypeSelect = useCallback(
    (type) => {
      setSelectedType(type)
      setIdentityNumber('')
      setErrors({})
      setDropdownOpen(false)
      if (onClearServerError) onClearServerError()
    },
    [onClearServerError]
  )

  const canSubmit = checked && identityNumber.trim().length > 0
  const identityHelper = errors.identity || serverError || ''

  if (!selectedType || !cfg) return null

  return (
    <div data-testid="login-step-identity">
      <IdentityHeader>
        {cfg.isDynamic ? (
          <SectionTitle>
            {formatDynamicMessage(intl, cfg.headline)}
          </SectionTitle>
        ) : (
          <SectionTitle>
            <FormattedMessage id="Masukkan" />
            <span className="accent">
              {' '}
              <FormattedMessage
                id={getIdentityAccentLabelId(selectedType)}
              />{' '}
            </span>
            <FormattedMessage id={getIdentityTitleSuffixId()} />
          </SectionTitle>
        )}
        {contextNumber ? (
          <IdentityContextLine data-testid="login-identity-context">
            {contextNumber}
          </IdentityContextLine>
        ) : null}
        {cfg.isDynamic ? (
          <SectionSubtitle>
            ({formatDynamicMessage(intl, cfg.subtitle)})
          </SectionSubtitle>
        ) : (
          <SectionSubtitle>
            (<FormattedMessage id={getIdentitySubtitleId(selectedType)} />)
          </SectionSubtitle>
        )}
      </IdentityHeader>

      <StepFormColumn>
        <FieldStack>
          {hasMultiple ? (
            <div
              ref={dropdownRef}
              style={{ position: 'relative', width: '100%' }}
            >
              <TypeDropdownBtn
                type="button"
                error={!!identityHelper}
                onClick={() => setDropdownOpen((v) => !v)}
              >
                {getTypeLabel(selectedType)}
                <span>▼</span>
              </TypeDropdownBtn>
              {dropdownOpen ? (
                <DropdownList>
                  {identityOptions.map((type) => (
                    <li key={type}>
                      <DropdownItem
                        type="button"
                        selected={type === selectedType}
                        onClick={() => handleTypeSelect(type)}
                      >
                        {getTypeLabel(type)}
                      </DropdownItem>
                    </li>
                  ))}
                </DropdownList>
              ) : null}
            </div>
          ) : null}
          <SecureFloatingInput
            label={
              cfg.isDynamic
                ? formatDynamicMessage(intl, cfg.fieldLabel)
                : intl.formatMessage({
                    id: getIdentityFieldLabelId(selectedType),
                  })
            }
            value={identityNumber}
            onChange={handleIdentityChange}
            error={!!identityHelper}
            helperText={
              cfg.isDynamic && identityHelper
                ? formatDynamicMessage(intl, identityHelper)
                : identityHelper
            }
            disabled={loading}
          />
          <TermsCheckbox
            checked={checked}
            onToggle={handleToggleChecked}
            disabled={loading}
            inline
          />
          <PrimaryBtn
            onClick={handleVerify}
            disabled={loading || !canSubmit}
            className={!canSubmit ? 'login-v3-btn-disabled' : ''}
          >
            {loading && <Spinner />}
            <PrimaryBtnText>
              <FormattedMessage id="Verifikasi" />
            </PrimaryBtnText>
          </PrimaryBtn>
        </FieldStack>

        <IdentityBackFooter
          onBack={onBack}
          disabled={loading}
          backLabelId={backLabelId}
        />
      </StepFormColumn>
    </div>
  )
}

export default injectIntl(IdentityVerifyPanel)
