import { useCallback, useState } from 'react'
import { useHistory } from 'react-router-dom'
import { useDispatch } from 'react-redux'
import { useIntl } from 'react-intl'
import {
  useResendOTP,
  useSendOtp,
  useVerifyOtp,
  useVerifyPolicyIdentitySession,
} from '../../../../../../request/query/auth'
import authAction from '../../../../../../redux/auth/actions'
import userAction from '../../../../../../redux/user/actions'
import { formatPhoneForApi, getDefaultCountry } from '../countryCodes'
import { normalizeFormLabelConfigs, stripMask } from '../identity-config'
import { resolvePostLoginRedirect } from '../redirect'
import {
  checkStatusUrl,
  consumeLoginStatusTab,
  setClaimStatusGate,
} from '../../../../../ClaimStatus/session'
import { getPublicClaimStatus } from '../../../../../ClaimStatus/mock'

const POLICY_IDENTITY_MISMATCH_ID =
  'Nomor KTP yang dimasukkan tidak sesuai dengan data pemegang polis.'
const STATUS_IDENTITY_MISMATCH_ID = 'Nomor KTP yang dimasukkan tidak sesuai'

function persistUserServices(serviceList) {
  if (serviceList && serviceList.length > 0) {
    window.sessionStorage.setItem('service_list', JSON.stringify(serviceList))
  }
}

export function useLoginFlow(config) {
  const intl = useIntl()
  const history = useHistory()
  const dispatch = useDispatch()

  const [loginTab, setLoginTab] = useState(() =>
    consumeLoginStatusTab() ? 'status' : 'submit'
  )
  const [authPath, setAuthPath] = useState(
    config.phoneOnly ? 'phone' : 'policy'
  )
  const [statusPath, setStatusPath] = useState('claim-number')
  const [loading, setLoading] = useState(false)
  const [policyNumber, setPolicyNumber] = useState('')
  const [claimNumber, setClaimNumber] = useState('')
  const [identityOptions, setIdentityOptions] = useState(null)
  const [formLabelConfigs, setFormLabelConfigs] = useState([])
  const [identityError, setIdentityError] = useState('')
  const [phone, setPhone] = useState('')
  const [selectedCountry, setSelectedCountry] = useState(() =>
    getDefaultCountry('id')
  )

  const { mutate: verifySession } = useVerifyPolicyIdentitySession()
  const { mutate: sendOtp } = useSendOtp()
  const { mutate: verifyOtp } = useVerifyOtp()
  const { mutate: resendOtp } = useResendOTP()

  const clearIdentityError = useCallback(() => {
    setIdentityError('')
  }, [])

  const completeStep1 = useCallback((np, _captcha, types, labelConfigs) => {
    setPolicyNumber(np)
    setIdentityError('')
    if (types && types.length > 0) {
      setIdentityOptions(types)
      setFormLabelConfigs(normalizeFormLabelConfigs(labelConfigs))
      setAuthPath('identity')
    } else {
      setIdentityOptions(null)
      setFormLabelConfigs([])
      setAuthPath('phone')
    }
  }, [])

  const switchToPhone = useCallback(() => {
    setIdentityOptions(null)
    setFormLabelConfigs([])
    setIdentityError('')
    setAuthPath('phone')
  }, [])

  const switchToPolicy = useCallback(() => {
    setIdentityError('')
    setAuthPath('policy')
  }, [])

  const backFromIdentity = useCallback(() => {
    setIdentityError('')
    if (loginTab === 'status') {
      setStatusPath('claim-number')
      return
    }
    setAuthPath('policy')
  }, [loginTab])

  const verifyIdentity = useCallback(
    (selectedType, identityValue) => {
      setLoading(true)
      setIdentityError('')
      verifySession(
        {
          policy_number: policyNumber,
          identity_type: selectedType,
          identity_value: identityValue,
        },
        {
          onSuccess: (response) => {
            setLoading(false)
            const data = response && response.data
            if (
              data &&
              typeof data.identity_matches === 'boolean' &&
              !data.identity_matches
            ) {
              setIdentityError(
                data.remark ||
                  intl.formatMessage({ id: POLICY_IDENTITY_MISMATCH_ID })
              )
              return
            }
            const vp = data && data.verify_policy_identity
            if (vp && vp.identity_matches) {
              let source = 'polis'
              let isAgentPolicy = false
              if (vp.is_agent_policy) {
                source = 'agency-policy'
                isAgentPolicy = true
              }
              if (vp.internal_id) {
                window.sessionStorage.setItem('internal_id', vp.internal_id)
                window.localStorage.setItem('source', source)
                window.localStorage.setItem(
                  'is_agent_policy',
                  vp.is_agent_policy
                )
              }
              dispatch({
                type: authAction.AUTH_VERIFY_OTP_SUCCESS,
                token: data.token,
                profile: data.user,
                serviceList: data.user && data.user.services,
              })
              dispatch({ type: authAction.AUTH_SUCCESS })
              dispatch({ type: userAction.GET_USER_DETAILS_REQUEST })
              history.push(
                resolvePostLoginRedirect({
                  internalId: vp.internal_id,
                  identitySource: source,
                  isAgentPolicy,
                  partnerOrigin: config.partnerOrigin,
                })
              )
              return
            }
            setIdentityError(
              intl.formatMessage({ id: POLICY_IDENTITY_MISMATCH_ID })
            )
          },
          onError: (err) => {
            setLoading(false)
            setIdentityError(
              (err && err.message) ||
                intl.formatMessage({ id: POLICY_IDENTITY_MISMATCH_ID })
            )
          },
        }
      )
    },
    [policyNumber, verifySession, history, dispatch, intl, config.partnerOrigin]
  )

  const handleSendOtp = useCallback(
    (country, phoneNumber, captchaToken, onDone) => {
      sendOtp(
        {
          payload: {
            captchaResponse: captchaToken,
            phone: formatPhoneForApi(country, phoneNumber),
          },
          languageCode: window.localStorage.getItem('lang') || 'id',
        },
        {
          onSuccess: (response) => {
            if (!response || !response.data || !response.data.operation_id) {
              onDone('Failed to send OTP. Please try again later.')
              return
            }
            window.sessionStorage.setItem(
              'operationId',
              response.data.operation_id
            )
            onDone()
          },
          onError: () => {
            onDone('Failed to send OTP. Please try again later.')
          },
        }
      )
    },
    [sendOtp]
  )

  const handleVerifyOtp = useCallback(
    (otpCode, onError) => {
      setLoading(true)
      verifyOtp(
        {
          body: {
            operation_id: window.sessionStorage.getItem('operationId'),
            otp: otpCode,
          },
        },
        {
          onSuccess: (response) => {
            setLoading(false)
            const data = response.data
            window.sessionStorage.removeItem('internal_id')
            persistUserServices(data.user && data.user.services)
            dispatch({
              type: authAction.AUTH_VERIFY_OTP_SUCCESS,
              token: data.token,
              profile: data.user,
              serviceList: data.user?.services,
            })
            dispatch({ type: authAction.AUTH_SUCCESS })
            dispatch({ type: userAction.GET_USER_DETAILS_REQUEST })
          },
          onError: () => {
            setLoading(false)
            onError()
          },
        }
      )
    },
    [verifyOtp, dispatch]
  )

  const handleResendOtp = useCallback(
    (onDone) => {
      if (!selectedCountry) return
      const operationId = window.sessionStorage.getItem('operationId')
      if (!operationId) return
      resendOtp(
        {
          mobileNo: formatPhoneForApi(selectedCountry, phone),
          operationId,
          medium: '',
          languageCode: window.localStorage.getItem('lang') || 'id',
        },
        {
          onSuccess: () => onDone(),
          onError: () => {
            onDone('Failed to resend OTP. Please try again later.')
          },
        }
      )
    },
    [resendOtp, selectedCountry, phone]
  )

  const handlePhoneOnlyBack = useCallback(() => {
    history.push('/')
  }, [history])

  const onPhoneCaptured = useCallback((country, phoneNumber) => {
    setSelectedCountry(country)
    setPhone(phoneNumber)
  }, [])

  const advanceStatusClaimNumber = useCallback((fullClaimNumber) => {
    if (!fullClaimNumber || !fullClaimNumber.trim()) return false
    if (!getPublicClaimStatus(fullClaimNumber)) return false
    setClaimNumber(fullClaimNumber)
    setIdentityError('')
    setStatusPath('identity')
    setIdentityOptions(['NIK'])
    return true
  }, [])

  const verifyStatusIdentity = useCallback(
    (_selectedType, identityValue) => {
      if (!claimNumber) return
      const record = getPublicClaimStatus(claimNumber)
      const expected = record && record.identity_number
      if (stripMask(identityValue || '') !== String(expected || '')) {
        setIdentityError(
          intl.formatMessage({ id: STATUS_IDENTITY_MISMATCH_ID })
        )
        return
      }
      setClaimStatusGate(claimNumber)
      history.push(checkStatusUrl(claimNumber))
    },
    [claimNumber, history, intl]
  )

  return {
    loginTab,
    setLoginTab,
    authPath,
    setAuthPath,
    statusPath,
    setStatusPath,
    loading,
    identityOptions,
    formLabelConfigs,
    identityError,
    clearIdentityError,
    phone,
    selectedCountry,
    policyNumber,
    claimNumber,
    completeStep1,
    switchToPhone,
    switchToPolicy,
    backFromIdentity,
    verifyIdentity,
    handleSendOtp,
    handleVerifyOtp,
    handleResendOtp,
    handlePhoneOnlyBack,
    onPhoneCaptured,
    advanceStatusClaimNumber,
    verifyStatusIdentity,
    handleBack: config.phoneOnly ? handlePhoneOnlyBack : backFromIdentity,
  }
}
