import { useEffect, useRef } from 'react'
import { CaptchaContainer } from './styles'

const REACT_APP_CAPTCHA_SITE_KEY = process.env.REACT_APP_CAPTCHA_SITE_KEY

const CaptchaField = ({ onVerify }) => {
  const captchaRef = useRef(null)
  const widgetIdRef = useRef(undefined)

  const loadCaptcha = () => {
    if (window.grecaptcha && window.grecaptcha.render && captchaRef.current) {
      widgetIdRef.current = window.grecaptcha.render(captchaRef.current, {
        sitekey: REACT_APP_CAPTCHA_SITE_KEY,
        callback: onVerify,
      })
    }
  }

  useEffect(() => {
    if (window.grecaptcha && window.grecaptcha.render) {
      loadCaptcha()
      return
    }

    const timers = [3, 2, 1].map((sec) =>
      setTimeout(
        () => {
          if (widgetIdRef.current === undefined) {
            loadCaptcha()
          }
        },
        (4 - sec) * 1000
      )
    )

    return () => {
      timers.forEach(clearTimeout)
    }
  }, [])

  return <CaptchaContainer ref={captchaRef} />
}

export default CaptchaField
