import { useCallback, useState } from 'react'
import { FormattedMessage, injectIntl } from 'react-intl'
import {
  PrimaryBtn,
  PrimaryBtnText,
} from '../../../../../../components/v2/Button'
import {
  InlineFieldAction,
  InlineFieldGrow,
  InlineFieldRow,
} from './InlineFieldRow'
import {
  ErrorText,
  KlmInputWrap,
  PolicyStepHeader,
  SectionSubtitle,
  SectionTitle,
  StepFormColumn,
} from '../styles'

const KLM_PREFIX = 'KLM - '

export function formatKlmClaimNumber(suffix) {
  const normalized = suffix.replace(/\s/g, '')
  return `KLM-${normalized}`
}

function KlmPrefixInput({ onComplete, intl }) {
  const [suffix, setSuffix] = useState('')
  const [error, setError] = useState('')

  const handleNext = useCallback(() => {
    if (!suffix.trim()) return
    setError('')
    const found = onComplete(formatKlmClaimNumber(suffix))
    if (found === false) {
      setError(intl.formatMessage({ id: 'Nomor klaim tidak ditemukan' }))
    }
  }, [suffix, intl, onComplete])

  const canSubmit = suffix.trim().length > 0

  return (
    <div data-testid="login-klm-step">
      <PolicyStepHeader>
        <SectionTitle>
          <FormattedMessage
            id="Masukkan Nomor Klaim untuk cek status klaim atau melihat detail klaim"
            values={{
              highlight: (chunks) => <span className="accent">{chunks}</span>,
            }}
          />
        </SectionTitle>
        <SectionSubtitle>
          (
          <FormattedMessage id="Nomor klaim terdapat di klaim notifikasi yang terkirim ke email Anda" />
          )
        </SectionSubtitle>
      </PolicyStepHeader>

      <StepFormColumn>
      <InlineFieldRow stacked>
        <InlineFieldGrow>
          <KlmInputWrap error={!!error} data-testid="login-klm-input">
            <span className="prefix">{KLM_PREFIX}</span>
            <input
              type="text"
              value={suffix}
              onChange={(e) => {
                setSuffix(e.target.value)
                setError('')
              }}
              aria-label={intl.formatMessage({ id: 'Nomor Klaim' })}
            />
          </KlmInputWrap>
          {error ? <ErrorText>{error}</ErrorText> : null}
        </InlineFieldGrow>
        <InlineFieldAction>
          <PrimaryBtn
            onClick={handleNext}
            disabled={!canSubmit}
            className={!canSubmit ? 'login-v3-btn-disabled' : ''}
          >
            <PrimaryBtnText>
              <FormattedMessage id="Mulai" />
            </PrimaryBtnText>
          </PrimaryBtn>
        </InlineFieldAction>
      </InlineFieldRow>
      </StepFormColumn>
    </div>
  )
}

export default injectIntl(KlmPrefixInput)
