import { useCallback } from 'react'
import IdentityVerifyPanel from './IdentityVerifyPanel'
import OtpModeV3 from './OtpModeV3'
import PhoneModeV3 from './PhoneModeV3'
import PolicyNumberPanel from './PolicyNumberPanel'

export function SubmitClaimPanel({ config, flow, locale }) {
  const handleSendOtp = useCallback(
    (country, phoneNumber, captcha, onDone) => {
      flow.onPhoneCaptured(country, phoneNumber)
      flow.handleSendOtp(country, phoneNumber, captcha, (error) => {
        onDone(error)
        if (!error) flow.setAuthPath('otp')
      })
    },
    [flow]
  )

  if (flow.authPath === 'otp' && flow.selectedCountry) {
    return (
      <OtpModeV3
        phone={flow.phone}
        country={flow.selectedCountry}
        loading={flow.loading}
        onVerifyOtp={flow.handleVerifyOtp}
        onResendOtp={flow.handleResendOtp}
        onBackToPhone={() => flow.setAuthPath('phone')}
      />
    )
  }

  if (flow.authPath === 'phone') {
    return (
      <PhoneModeV3
        onSendOtp={handleSendOtp}
        onSwitchToPolicy={config.phoneOnly ? undefined : flow.switchToPolicy}
        onBack={config.phoneOnly ? flow.handlePhoneOnlyBack : undefined}
        showPolicyToggle={!config.phoneOnly}
        requireCaptcha={config.requireCaptcha}
      />
    )
  }

  if (flow.authPath === 'identity') {
    return (
      <IdentityVerifyPanel
        identityOptions={flow.identityOptions}
        formLabelConfigs={flow.formLabelConfigs}
        contextNumber={flow.policyNumber}
        loading={flow.loading}
        serverError={flow.identityError}
        onClearServerError={flow.clearIdentityError}
        backLabelId="Ubah Nomor Polis"
        onBack={flow.backFromIdentity}
        onVerify={flow.verifyIdentity}
      />
    )
  }

  return (
    <PolicyNumberPanel
      onComplete={flow.completeStep1}
      onSwitchToPhone={flow.switchToPhone}
    />
  )
}
