import { memo, useCallback } from 'react'
import { CheckboxRow, CheckboxLabel } from './styles'
import { CheckboxOff, CheckboxOn } from '../icons'

const Checkbox = memo(({ checked, onChange, disabled, label, className }) => {
  const handleClick = useCallback(() => {
    if (!disabled) onChange(!checked)
  }, [checked, onChange, disabled])

  return (
    <CheckboxRow onClick={handleClick} className={className}>
      {checked ? <CheckboxOn /> : <CheckboxOff />}
      {label && <CheckboxLabel>{label}</CheckboxLabel>}
    </CheckboxRow>
  )
})

export { CheckboxRow, CheckboxLabel }
export default Checkbox
